import { spawn } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    // Read the pinned test cases
    const testCasesPath = join(referenceDir, 'pinned-test-cases.txt');
    const testCases = readFileSync(testCasesPath, 'utf-8');

    // Create a test runner that imports the submission and runs all cases
    const testRunnerCode = `
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { dedupeSorted } from '${submissionDir}/answer.mjs';

let passCount = 0;
let failCount = 0;
let testResults = [];

const originalTest = test;
globalThis.test = (name, fn) => {
  try {
    fn();
    passCount++;
    testResults.push({ name, status: 'pass' });
  } catch (e) {
    failCount++;
    testResults.push({ name, status: 'fail', error: e.message });
    throw e;
  }
};

${testCases}

console.log(JSON.stringify({ passCount, failCount, testResults }));
`;

    const runnerPath = join(referenceDir, 'test-runner.mjs');
    writeFileSync(runnerPath, testRunnerCode);

    // Execute the test runner
    return new Promise((resolve) => {
      let stdout = '';
      let stderr = '';

      const proc = spawn(process.execPath, [runnerPath], {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 10000
      });

      proc.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        try {
          // Parse the JSON output from the test runner
          const lastLine = stdout.trim().split('\n').pop();
          const results = JSON.parse(lastLine);

          // Check if all tests passed
          if (results.failCount === 0 && results.passCount > 0) {
            resolve({
              accept: true,
              reason: `All ${results.passCount} test cases passed. Tests: ${results.testResults.map(t => t.name).join(', ')}`
            });
          } else {
            const failedTests = results.testResults.filter(t => t.status === 'fail').map(t => `${t.name}: ${t.error}`).join('; ');
            resolve({
              accept: false,
              reason: `${results.failCount} test(s) failed: ${failedTests}`
            });
          }
        } catch (e) {
          resolve({
            accept: false,
            reason: `Test execution error: ${e.message}. stdout: ${stdout.slice(-200)}, stderr: ${stderr.slice(-200)}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
      });
    });
  } catch (e) {
    return {
      accept: false,
      reason: `Gate setup error: ${e.message}`
    };
  }
}

