import { spawn } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    // Read the pinned test cases
    const testCasesPath = join(referenceDir, 'pinned-test-cases.txt');
    const testCases = readFileSync(testCasesPath, 'utf-8');

    // Create a minimal test runner that captures results without relying on node:test output parsing
    const testRunnerCode = `
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { dedupeSorted } from '${submissionDir}/answer.mjs';

let passCount = 0;
let failCount = 0;
const testNames = [];
const failedTests = [];

const originalTest = test;
globalThis.test = (name, fn) => {
  testNames.push(name);
  try {
    fn();
    passCount++;
  } catch (e) {
    failCount++;
    failedTests.push({ name, error: e.message });
    throw e;
  }
};

${testCases}

// Write results to a file to avoid parsing stdout
const fs = require('fs');
fs.writeFileSync('${referenceDir}/results.json', JSON.stringify({
  passCount,
  failCount,
  testNames,
  failedTests
}));
`;

    const runnerPath = join(referenceDir, 'test-runner.mjs');
    writeFileSync(runnerPath, testRunnerCode);

    // Execute the test runner
    return new Promise((resolve) => {
      const proc = spawn(process.execPath, [runnerPath], {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 10000,
        env: {}
      });

      let stderr = '';
      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        try {
          // Read results from file
          const resultsPath = join(referenceDir, 'results.json');
          const resultsJson = readFileSync(resultsPath, 'utf-8');
          const results = JSON.parse(resultsJson);

          // Verify all tests ran and passed
          const expectedTestCount = 8; // 8 test cases in the pinned suite
          const totalTestsRun = results.passCount + results.failCount;

          if (totalTestsRun !== expectedTestCount) {
            resolve({
              accept: false,
              reason: `Expected ${expectedTestCount} tests to run, but only ${totalTestsRun} ran (${results.passCount} passed, ${results.failCount} failed). Tests run: ${results.testNames.join(', ')}`
            });
            return;
          }

          if (results.failCount === 0 && results.passCount === expectedTestCount) {
            resolve({
              accept: true,
              reason: `All ${expectedTestCount} pinned test cases passed`
            });
          } else {
            const failedList = results.failedTests.map(t => `${t.name}: ${t.error}`).join('; ');
            resolve({
              accept: false,
              reason: `${results.failCount} test(s) failed: ${failedList}`
            });
          }
        } catch (e) {
          resolve({
            accept: false,
            reason: `Failed to parse test results: ${e.message}. stderr: ${stderr.slice(-300)}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
      });
    });
  } catch (e) {
    return {
      accept: false,
      reason: `Gate setup error: ${e.message}`
    };
  }
}

